import random
from sc2 import run_game, maps, Race, Difficulty
from sc2.player import Bot, Computer
from sc2.constants import *
from sc2.bot_ai import BotAI

class ThreeBaseThreeStargateBot(BotAI):
    async def on_step(self, iteration):
        await self.distribute_workers()

        # Chrono boost active nexuses
        for nexus in self.townhalls.ready:
            if nexus.energy >= 50:
                abilities = await self.get_available_abilities(nexus)
                if AbilityId.EFFECT_CHRONOBOOSTENERGYCOST in abilities:
                    targets = self.structures.of_type(
                        {UnitTypeId.GATEWAY, UnitTypeId.CYBERNETICSCORE, UnitTypeId.STARGATE}
                    ).ready
                    if targets:
                        target = targets.closest_to(nexus)
                        nexus(AbilityId.EFFECT_CHRONOBOOSTENERGYCOST, target)
                    else:
                        nexus(AbilityId.EFFECT_CHRONOBOOSTENERGYCOST, nexus)

        # If no nexuses left, worker rush
        if not self.townhalls:
            for worker in self.workers.idle | self.workers.gathering:
                worker.attack(self.enemy_start_locations[0])
            return

        # Build pylons when supply is low
        if (
            self.supply_left < 5
            and self.already_pending(UnitTypeId.PYLON) == 0
            and self.can_afford(UnitTypeId.PYLON)
        ):
            nex = self.townhalls.ready.random_or(self.townhalls.first)
            pos = nex.position.towards(self.game_info.map_center, random.randrange(4, 8))
            await self.build(UnitTypeId.PYLON, near=pos)

        # Build Gateway if none exists
        if (
            self.structures(UnitTypeId.GATEWAY).amount + self.already_pending(UnitTypeId.GATEWAY) < 1
            and self.structures(UnitTypeId.PYLON).ready
            and self.can_afford(UnitTypeId.GATEWAY)
        ):
            pylon = self.structures(UnitTypeId.PYLON).ready.random
            await self.build(UnitTypeId.GATEWAY, near=pylon)

        # Build Cybernetics Core if Gateway is ready and no Core exists
        if (
            self.structures(UnitTypeId.GATEWAY).ready
            and self.structures(UnitTypeId.CYBERNETICSCORE).amount + self.already_pending(UnitTypeId.CYBERNETICSCORE) < 1
            and self.can_afford(UnitTypeId.CYBERNETICSCORE)
        ):
            pylon = self.structures(UnitTypeId.PYLON).ready.random
            await self.build(UnitTypeId.CYBERNETICSCORE, near=pylon)

        # Expand up to 3 Nexuses
        if (
            self.townhalls.amount + self.already_pending(UnitTypeId.NEXUS) < 3
            and self.can_afford(UnitTypeId.NEXUS)
        ):
            await self.expand_now()

        # Build Assimilators near completed Nexuses
        for nexus in self.townhalls.ready:
            vgs = self.vespene_geyser.closer_than(10, nexus)
            for vg in vgs:
                if (
                    not self.gas_buildings.closer_than(1.0, vg)
                    and self.can_afford(UnitTypeId.ASSIMILATOR)
                    and self.already_pending(UnitTypeId.ASSIMILATOR) < 2
                ):
                    worker = self.select_build_worker(vg.position)
                    if worker:
                        worker.build(UnitTypeId.ASSIMILATOR, vg)
                        break

        # Build Stargates when at least 3 Nexuses and less than 3 Stargates
        if (
            self.townhalls.ready.amount >= 3
            and self.structures(UnitTypeId.CYBERNETICSCORE).ready
            and self.structures(UnitTypeId.STARGATE).amount + self.already_pending(UnitTypeId.STARGATE) < 3
            and self.can_afford(UnitTypeId.STARGATE)
        ):
            pylon = self.structures(UnitTypeId.PYLON).ready.random
            await self.build(UnitTypeId.STARGATE, near=pylon)

        # Train Probes on undersaturated Nexuses
        for nexus in self.townhalls.ready.idle:
            if (
                self.can_afford(UnitTypeId.PROBE)
                and nexus.assigned_harvesters < nexus.ideal_harvesters
                and self.supply_workers < 70
            ):
                nexus.train(UnitTypeId.PROBE)

        # Train Void Rays at idle Stargates if at least 3 Nexuses
        if self.townhalls.ready.amount >= 3:
            for stargate in self.structures(UnitTypeId.STARGATE).ready.idle:
                if self.can_afford(UnitTypeId.VOIDRAY):
                    stargate.train(UnitTypeId.VOIDRAY)

        # Attack with Void Rays if more than 5
        voidrays = self.units(UnitTypeId.VOIDRAY).ready
        if voidrays.amount > 5:
            for vr in voidrays.idle:
                vr.attack(self.enemy_start_locations[0])

        # Basic defense: attack with all units if enemy units are near base
        for nexus in self.townhalls.ready:
            enemies = self.enemy_units.closer_than(20, nexus)
            if enemies:
                for unit in self.units.ready:
                    unit.attack(enemies.closest_to(unit))

run_game(
    maps.get("(2)CatalystLE"),
    [
        Bot(Race.Protoss, ThreeBaseThreeStargateBot()),
        Computer(Race.Protoss, Difficulty.Easy)
    ],
    realtime=False,
)
